AND VAL_DATE = ( select max(val_date) val_date from RSK_VALTBL_SUM_ASSET_SUB where PTL_ID = #{portfolioId,jdbcType=VARCHAR} and VAL_DATE <= TO_DATE(#{cdate},'YYYY-MM-DD') )
