delete from PTL_SEC_PIERCE_VALUTION
where CDATE = #{cdate,jdbcType=DATE}
  and PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}

delete from PTL_SEC_PIERCE_VALUTION_DETAIL
