mapper.select:
SELECT DISTINCT fp1.FINPROD_ID "finprodId",tt.VAL_DATE "valDate" FROM PTL_SEC_VALUTION psv LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = psv.FINPROD_ID AND fp.FINPROD_TYPE2='F17' LEFT JOIN FIN_PRODUCT fp1 ON fp1.FINPROD_MARKET_ID = psv.PORTFOLIO_ID LEFT JOIN ( SELECT PTL_ID,max(VAL_DATE) VAL_DATE from( SELECT PTL_ID,min(VAL_DATE) VAL_DATE FROM RSK_VALTBL_ASSET_SUB rvas WHERE VAL_DATE>=#{dateMin,jdbcType=DATE} AND VAL_DATE < #{dateMax,jdbcType=DATE} GROUP BY PTL_ID
UNION ALL SELECT ZGPLAN_ID PTL_ID,max(CDATE) VAL_DATE FROM PTL_SEC_PIERCE_VALUTION_DETAIL WHERE CDATE >=#{dateMin,jdbcType=DATE} AND CDATE < #{dateMax,jdbcType=DATE} GROUP BY ZGPLAN_ID
)GROUP BY PTL_ID)tt ON tt.PTL_ID = fp.FINPROD_MARKET_ID WHERE psv.CDATE >= #{dateMin,jdbcType=DATE} AND psv.CDATE <=#{dateMax,jdbcType=DATE}
AND ( psv.PORTFOLIO_ID in (select PORTFOLIO_ID from FIN_PRODUCT_ADD where FIN_PRODUCT_ADD.FINPROD_ID in
null) OR PORTFOLIO_ID IN (
