)

SELECT * FROM( SELECT row_number() over (partition by T1.PTL_ID,left(T1.SUB_CODE,4) order by LENGTH(T1.SUB_CODE) desc) as num, T1.VAL_DATE VAL_DATE, T1.PTL_ID PTL_ID, T1.SUB_CODE SUB_CODE, T1.FINPROD_ID FINPROD_ID, T1.SECURITY_QUANTITY SECURITY_QUANTITY, T1.UNIT_COST UNIT_COST, T1.SECURITY_COST SECURITY_COST, T1.CTNWR CTNWR, T1.MCP MCP, T1.SMV SMV, T1.MCR MCR, T1.VALUE_ADDED VALUE_ADDED, T1.SUSPENSION_INFO SUSPENSION_INFO, T1.EQUITY_INFO EQUITY_INFO, T1.IMP_MODE IMP_MODE, T1.CREATE_USER CREATE_USER, T1.CREATE_DEPT CREATE_DEPT, T1.CREATE_TIME CREATE_TIME, T1.UPDATE_USER UPDATE_USER, T1.UPDATE_TIME UPDATE_TIME, T2.FINPROD_TYPE2, T2.FINPROD_MARKET_ID FROM RSK_VALTBL_ASSET_SUB T1 INNER JOIN ( SELECT PTL_ID , MAX(VAL_DATE) VAL_DATE FROM RSK_VALTBL_ASSET_SUB GROUP BY PTL_ID ) TT2 ON T1.VAL_DATE = TT2.VAL_DATE AND T1.PTL_ID = TT2.PTL_ID left join FIN_PRODUCT T2 on T1.FINPROD_ID = T2.FINPROD_ID where T1.SUB_CODE IN ('120410','12041001','2231','22301','22310101')
AND T1.PTL_ID = #{portfolioId,jdbcType=VARCHAR}
)t WHERE t.num =1
